import argparse
import csv
import json
import statistics
import sys
from pathlib import Path
from typing import Iterable, List, Optional, Union


def parse_args() -> argparse.Namespace:
    parser = argparse.ArgumentParser(
        description="Compute basic statistics for a numeric column in a CSV/TSV file."
    )
    parser.add_argument("input", type=Path, help="Path to input CSV/TSV file")
    parser.add_argument(
        "-c",
        "--column",
        required=True,
        help="Column name or zero-based index to analyze (e.g. '2' or 'price')",
    )
    parser.add_argument(
        "-d",
        "--delimiter",
        default=None,
        help="Delimiter character (default: auto-detect comma or tab)",
    )
    parser.add_argument(
        "-o",
        "--output",
        type=Path,
        default=None,
        help="Optional output JSON file to write statistics",
    )
    parser.add_argument(
        "--skip-invalid",
        action="store_true",
        help="Skip non-numeric values instead of failing",
    )
    return parser.parse_args()


def detect_delimiter(path: Path) -> str:
    sample_size = 1024
    with path.open("r", encoding="utf-8", errors="ignore") as fh:
        sample = fh.read(sample_size)
    if "\t" in sample and sample.count("\t") > sample.count(","):
        return "\t"
    return ","


def _is_int_string(s: str) -> bool:
    try:
        int(s)
        return True
    except ValueError:
        return False


def read_numbers_from_csv(
    path: Path,
    column: Union[str, int],
    delimiter: Optional[str] = None,
    skip_invalid: bool = False,
) -> List[float]:
    if not path.exists():
        raise FileNotFoundError(f"Input file not found: {path}")
    delim = delimiter or detect_delimiter(path)
    numbers: List[float] = []
    with path.open("r", encoding="utf-8", errors="replace", newline="") as fh:
        # Decide whether to use DictReader or reader
        try:
            peek = fh.readline()
            if not peek:
                return []
            fh.seek(0)
            has_header = csv.Sniffer().has_header(peek + fh.readline())
            fh.seek(0)
        except Exception:
            fh.seek(0)
            has_header = False
        if isinstance(column, int) or (isinstance(column, str) and _is_int_string(column)):
            index = int(column)
            reader = csv.reader(fh, delimiter=delim)
            for row_num, row in enumerate(reader, start=1):
                if index >= len(row):
                    if skip_invalid:
                        continue
                    raise IndexError(f"Row {row_num} has no column at index {index}")
                raw = row[index].strip()
                if raw == "":
                    if skip_invalid:
                        continue
                    raise ValueError(f"Empty value at row {row_num}, column {index}")
                try:
                    numbers.append(float(raw))
                except ValueError:
                    if skip_invalid:
                        continue
                    raise ValueError(f"Non-numeric value '{raw}' at row {row_num}, column {index}")
        else:
            if not has_header:
                raise ValueError("Column specified by name but file has no header row")
            reader = csv.DictReader(fh, delimiter=delim)
            key = str(column)
            for row_num, row in enumerate(reader, start=2):
                if key not in row:
                    raise KeyError(f"Column '{key}' not found in header")
                raw = row[key].strip()
                if raw == "":
                    if skip_invalid:
                        continue
                    raise ValueError(f"Empty value at row {row_num}, column '{key}'")
                try:
                    numbers.append(float(raw))
                except ValueError:
                    if skip_invalid:
                        continue
                    raise ValueError(f"Non-numeric value '{raw}' at row {row_num}, column '{key}'")
    return numbers


def compute_stats(values: Iterable[float]) -> dict:
    vals = list(values)
    if not vals:
        raise ValueError("No numeric values to compute statistics")
    stats = {
        "count": len(vals),
        "sum": sum(vals),
        "min": min(vals),
        "max": max(vals),
        "mean": statistics.mean(vals),
    }
    if len(vals) > 1:
        stats["median"] = statistics.median(vals)
        stats["stdev"] = statistics.pstdev(vals) if len(vals) > 0 else 0.0
    else:
        stats["median"] = vals[0]
        stats["stdev"] = 0.0
    return stats


def write_json(path: Optional[Path], data: dict) -> None:
    if path is None:
        json.dump(data, sys.stdout, indent=2)
        sys.stdout.write("\n")
    else:
        path.parent.mkdir(parents=True, exist_ok=True)
        with path.open("w", encoding="utf-8") as fh:
            json.dump(data, fh, indent=2)


def main() -> None:
    args = parse_args()
    column_arg: Union[str, int]
    column_arg = args.column if not _is_int_string(args.column) else int(args.column)
    try:
        numbers = read_numbers_from_csv(
            args.input, column_arg, delimiter=args.delimiter, skip_invalid=args.skip_invalid
        )
        stats = compute_stats(numbers)
        metadata = {
            "input": str(args.input),
            "column": args.column,
            "delimiter": args.delimiter or "auto",
            "values_used": stats["count"],
        }
        result = {"metadata": metadata, "statistics": stats}
        write_json(args.output, result)
    except Exception as exc:
        sys.stderr.write(f"Error: {exc}\n")
        sys.exit(1)


if __name__ == "__main__":
    main()

