import argparse
import json
import logging
import re
import sys
from collections import Counter
from pathlib import Path
from typing import Dict, Iterable, List


def find_text_files(directory: Path, pattern: str = "*.txt") -> List[Path]:
    if not directory.exists():
        raise FileNotFoundError(f"Directory does not exist: {directory}")
    if not directory.is_dir():
        raise NotADirectoryError(f"Not a directory: {directory}")
    return [p for p in directory.rglob(pattern) if p.is_file()]


def read_file(path: Path, encoding: str = "utf-8") -> str:
    try:
        with path.open("r", encoding=encoding) as fh:
            return fh.read()
    except Exception as exc:
        raise IOError(f"Failed to read {path}: {exc}") from exc


def tokenize(text: str) -> List[str]:
    return re.findall(r"\b\w+\b", text.lower())


def count_words(paths: Iterable[Path]) -> Dict[str, int]:
    counter: Counter = Counter()
    for path in paths:
        try:
            text = read_file(path)
            tokens = tokenize(text)
            counter.update(tokens)
        except Exception as exc:
            logging.warning("Skipping %s: %s", path, exc)
    return dict(counter)


def write_json(data: Dict[str, int], out_path: Path, ensure_ascii: bool = False) -> None:
    out_path.parent.mkdir(parents=True, exist_ok=True)
    try:
        with out_path.open("w", encoding="utf-8") as fh:
            json.dump(data, fh, ensure_ascii=ensure_ascii, indent=2)
    except Exception as exc:
        raise IOError(f"Failed to write {out_path}: {exc}") from exc


def parse_args(argv: List[str]) -> argparse.Namespace:
    parser = argparse.ArgumentParser(description="Count word frequencies in text files under a directory.")
    parser.add_argument("directory", type=Path, help="Directory to scan for text files")
    parser.add_argument(
        "-p",
        "--pattern",
        default="*.txt",
        help="Glob pattern to match files (default: '*.txt')",
    )
    parser.add_argument(
        "-o",
        "--output",
        type=Path,
        default=Path("word_counts.json"),
        help="Output JSON file (default: word_counts.json)",
    )
    parser.add_argument("-n", "--top", type=int, default=20, help="Number of top words to display")
    parser.add_argument("-v", "--verbose", action="store_true", help="Enable verbose logging")
    return parser.parse_args(argv)


def top_n(data: Dict[str, int], n: int) -> List[tuple]:
    return sorted(data.items(), key=lambda kv: kv[1], reverse=True)[:n]


def main(argv: List[str] | None = None) -> int:
    args = parse_args(sys.argv[1:] if argv is None else argv)
    logging.basicConfig(level=logging.DEBUG if args.verbose else logging.INFO, format="%(levelname)s: %(message)s")

    try:
        files = find_text_files(args.directory, args.pattern)
    except Exception as exc:
        logging.error("Error locating files: %s", exc)
        return 2

    if not files:
        logging.info("No files found matching %s in %s", args.pattern, args.directory)
        return 0

    logging.info("Found %d files", len(files))
    counts = count_words(files)
    if not counts:
        logging.info("No words counted.")
        return 0

    try:
        write_json(counts, args.output)
    except Exception as exc:
        logging.error("Failed to write output: %s", exc)
        return 3

    logging.info("Wrote counts to %s", args.output)
    for word, freq in top_n(counts, args.top):
        print(f"{word}: {freq}")
    return 0


if __name__ == "__main__":
    raise SystemExit(main())

