from dataclasses import dataclass
from typing import Any, Callable, Generic, TypeVar, cast

T = TypeVar("T")
U = TypeVar("U")


class Result(Generic[T]):
    """Base type for Result variants."""


@dataclass(frozen=True)
class Ok(Result[T]):
    value: T


@dataclass(frozen=True)
class Err(Result[T]):
    message: str


def parse_int(s: str) -> Result[int]:
    try:
        n = int(s)
        return Ok(n)
    except ValueError:
        return Err("Invalid integer")


def divide_safe(a: int, b: int) -> Result[int]:
    if b == 0:
        return Err("Division by zero")
    return Ok(a // b)


def bind(result: Result[T], func: Callable[[T], Result[U]]) -> Result[U]:
    if isinstance(result, Ok):
        return func(result.value)
    return cast(Result[U], result)


def print_result(result: Result[Any]) -> None:
    if isinstance(result, Ok):
        print(f"Result: {result.value}")
    elif isinstance(result, Err):
        print(f"Error: {result.message}")
    else:
        print("Error: Unknown result")


def main() -> None:
    # Test 1: parse_int("10") then divide by 2 -> "Result: 5"
    r1 = bind(parse_int("10"), lambda n: divide_safe(n, 2))
    print_result(r1)

    # Test 2: parse_int("10") then divide by 0 -> "Error: Division by zero"
    r2 = bind(parse_int("10"), lambda n: divide_safe(n, 0))
    print_result(r2)

    # Test 3: parse_int("abc") -> "Error: Invalid integer"
    r3 = parse_int("abc")
    print_result(r3)


if __name__ == "__main__":
    main()

