def read_text(path: Path) -> str:
    """Read and return the text content of a file."""
    try:
        with path.open("r", encoding="utf-8") as fh:
            return fh.read()
    except OSError as exc:
        raise RuntimeError(f"Failed to read {path}: {exc}") from exc


def tokenize(text: str, case_insensitive: bool = True) -> List[str]:
    """Return a list of word tokens from text."""
    if case_insensitive:
        text = text.lower()
    return WORD_RE.findall(text)


def top_n_words(tokens: Iterable[str], n: int) -> List[Tuple[str, int]]:
    """Return the top n most common tokens as (word, count) pairs."""
    counter = Counter(tokens)
    return counter.most_common(n)


def format_output(pairs: Iterable[Tuple[str, int]]) -> str:
    """Format word/count pairs into a human-readable string."""
    return "\n".join(f"{word}\t{count}" for word, count in pairs)


def write_output(content: str, path: Path | None) -> None:
    """Write content to a file or stdout if path is None."""
    if path is None:
        print(content)
        return
    try:
        with path.open("w", encoding="utf-8") as fh:
            fh.write(content)
    except OSError as exc:
        raise RuntimeError(f"Failed to write to {path}: {exc}") from exc


def parse_args(argv: Iterable[str] | None = None) -> argparse.Namespace:
    parser = argparse.ArgumentParser(
        prog="wordfreq",
        description="Compute the top N most common words in a text file.",
    )
