from pathlib import Path
from collections import Counter
from typing import Iterable, List, Tuple, Optional
import argparse
import re
import json
import sys


WORD_RE = re.compile(r"\b\w+\b", flags=re.UNICODE)


def find_text_files(root: Path, suffixes: Tuple[str, ...], recursive: bool) -> List[Path]:
    if not root.exists():
        raise FileNotFoundError(f"Root path does not exist: {root}")
    if root.is_file():
        return [root] if root.suffix.lower() in suffixes else []
    if recursive:
        return [p for p in root.rglob("*") if p.is_file() and p.suffix.lower() in suffixes]
    return [p for p in root.iterdir() if p.is_file() and p.suffix.lower() in suffixes]


def count_words_in_file(path: Path) -> Counter:
    counter: Counter[str] = Counter()
    try:
        with path.open("r", encoding="utf-8", errors="replace") as fh:
            for line in fh:
                words = WORD_RE.findall(line.lower())
                counter.update(words)
    except Exception as exc:
        raise IOError(f"Failed to read {path}: {exc}") from exc
    return counter


def aggregate_counts(paths: Iterable[Path]) -> Counter:
    total: Counter[str] = Counter()
    for p in paths:
        try:
            total.update(count_words_in_file(p))
        except IOError as exc:
            print(f"Warning: {exc}", file=sys.stderr)
    return total


def write_json(output_path: Path, data: List[Tuple[str, int]]) -> None:
    payload = [{"word": w, "count": c} for w, c in data]
    with output_path.open("w", encoding="utf-8") as fh:
        json.dump(payload, fh, ensure_ascii=False, indent=2)


def print_top(counter: Counter, top_n: int) -> None:
    for i, (word, count) in enumerate(counter.most_common(top_n), start=1):
        print(f"{i:3}. {word:<20} {count}")


def parse_args(argv: Optional[List[str]] = None) -> argparse.Namespace:
    parser = argparse.ArgumentParser(description="Count word frequencies in text files.")
    parser.add_argument("path", type=Path, help="File or directory to scan")
    parser.add_argument(
        "-s",
        "--suffixes",
        nargs="+",
        default=[".txt", ".md", ".py"],
        help="File suffixes to include (default: .txt .md .py)",
    )
    parser.add_argument("-n", "--top", type=int, default=20, help="Number of top words to show")
    parser.add_argument("-o", "--output", type=Path, help="Path to write JSON output")
    parser.add_argument("-r", "--recursive", action="store_true", help="Recursively scan directories")
    parser.add_argument("-v", "--verbose", action="store_true", help="Enable verbose logging")
    return parser.parse_args(argv)


def main() -> None:
    args = parse_args()
    suffixes = tuple(s if s.startswith(".") else f".{s}" for s in args.suffixes)
    try:
        files = find_text_files(args.path, suffixes, args.recursive)
    except FileNotFoundError as exc:
        print(f"Error: {exc}", file=sys.stderr)
        sys.exit(2)
    if not files:
        print("No matching files found.", file=sys.stderr)
        sys.exit(1)
    if args.verbose:
        print(f"Found {len(files)} files. Processing...")
    total = aggregate_counts(files)
    if not total:
        print("No words found in the provided files.")
        return
    print_top(total, args.top)
    if args.output:
        top_data = total.most_common(args.top)
        try:
            write_json(args.output, top_data)
            if args.verbose:
                print(f"Wrote top {args.top} words to {args.output}")
        except Exception as exc:
            print(f"Failed to write output: {exc}", file=sys.stderr)


if __name__ == "__main__":
    main()

