from dataclasses import dataclass
from typing import TypedDict


class Profile(TypedDict):
    age: int
    city: str


@dataclass
class User:
    name: str
    profile: Profile


def getCity(user: User) -> str:
    return user.profile["city"]


def main():
    user = User(name="Alice", profile={"age": 30, "city": "NYC"})
    print(f"City: {getCity(user)}")


if __name__ == "__main__":
    main()
